<template><section v-if="allowed" class="shop-editor"><h3>后台更正店铺资料</h3><p>用户仅可首次提交。后台更正会保留原材料、重新审核，并下架当前出售商品；求购不受店铺状态影响。</p><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top" :disabled="busy"><el-form-item label="店铺名称"><el-input v-model="form.shopName" maxlength="40" /></el-form-item><el-form-item label="店铺介绍"><el-input v-model="form.shopIntro" type="textarea" :rows="3" maxlength="500" /></el-form-item><el-form-item label="已验证手机号"><span>{{member.phone||'未验证（旧版资料）'}}</span></el-form-item><el-checkbox v-model="changePhone" :disabled="busy">核验新的手机号</el-checkbox><template v-if="changePhone"><el-form-item label="新手机号"><el-input v-model="phone" maxlength="11" placeholder="本人提供的中国大陆手机号" /></el-form-item><el-form-item label="短信验证码"><div class="phone-code"><el-input v-model="code" maxlength="6" /><el-button :disabled="busy||remaining>0||!smsReady" @click="sendCode">{{remaining>0?remaining+' 秒后重发':'发送验证码'}}</el-button><el-button :disabled="busy||!challenge||!smsReady" @click="verify">核验</el-button></div></el-form-item><el-alert :title="phoneTicket?'手机号已核验；保存更正后生效':smsReady?'需新号码本人接收验证码，5 分钟内核验并保存':'短信服务未配置，不能更换手机号'" :type="phoneTicket?'success':'info'" :closable="false" /></template><el-form-item label="店铺证明材料（最多 3 张）"><div><div class="proof-list"><div v-for="(p,i) in form.images" :key="p"><el-image :src="mediaUrl(p)" fit="cover" :preview-src-list="[mediaUrl(p)]" preview-teleported /><el-button link type="danger" @click="form.images.splice(i,1)">移除</el-button></div></div><input :disabled="busy||form.images.length>=3" type="file" accept="image/jpeg,image/png" aria-label="上传店铺更正材料" @change="upload" /></div></el-form-item><el-form-item label="更正原因（必填）"><el-input v-model="form.note" maxlength="500" type="textarea" :rows="2" /></el-form-item><el-button type="primary" :loading="busy" :disabled="!ready" @click="save">保存更正并重新审核</el-button></el-form><h3>资料与审核历史</h3><el-button link :disabled="busy" @click="history(1)">刷新历史</el-button><el-empty v-if="!records.length" description="暂无新版本记录，首次更正时会留存旧资料" :image-size="45" /><div v-for="item in records" :key="item.id" class="history"><b>版本 {{item.revision}} · {{statusText[item.shopStatus]}}</b><p>{{item.createdAt?.replace('T',' ')}} · {{item.adminId?'后台 '+item.adminId:'用户首次提交 / 旧版留档'}}</p><p>{{item.shopName}} · {{item.phone||'无已验证手机号'}}</p><p>{{item.shopIntro}}</p><p>原因：{{item.note}}</p><el-image v-for="p in parseImages(item.shopProof)" :key="p" :src="mediaUrl(p)" :preview-src-list="[mediaUrl(p)]" preview-teleported fit="cover" /></div><el-button v-if="records.length<total" :disabled="busy" @click="history(page+1)">更多历史</el-button></section></template>
<script setup>
import {reactive,ref,watch,onMounted,onBeforeUnmount} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import auth from '@/plugins/auth';import request from '@/utils/request';import {getToken} from '@/utils/auth';import {mediaUrl,statusText} from '@/api/boost';import {authorizeMedia} from '@/utils/boostMedia'
const props=defineProps({member:{type:Object,required:true}}),emit=defineEmits(['saved']),allowed=auth.hasPermi('boost:shops:review'),parseImages=v=>{try{return JSON.parse(v||'[]')}catch{return []}}
const form=reactive({shopName:props.member.shopName,shopIntro:props.member.shopIntro,images:parseImages(props.member.shopProof),note:''}),changePhone=ref(false),phone=ref(''),code=ref(''),challenge=ref(''),phoneTicket=ref(''),busy=ref(false),error=ref(''),ready=ref(false),smsReady=ref(false),records=ref([]),total=ref(0),remaining=ref(0);let alive=true,page=1,until=0
const timer=setInterval(()=>{remaining.value=Math.max(0,Math.ceil((until-Date.now())/1000))},1000);onBeforeUnmount(()=>{alive=false;clearInterval(timer)});watch(phone,()=>{challenge.value='';phoneTicket.value='';code.value=''});watch(changePhone,()=>{challenge.value='';phoneTicket.value='';phone.value='';code.value=''})
const endpoint='/boost-admin/shops/'+props.member.id,valid=token=>alive&&getToken()===token
async function history(next=1){const token=getToken();try{const r=await request({url:endpoint+'/history',params:{page:next}});if(!valid(token))return;records.value=next===1?r.data.items:[...records.value,...r.data.items];total.value=r.data.total;page=next}catch(e){if(valid(token))error.value=e.message}}
onMounted(async()=>{if(!allowed)return;const token=getToken();try{const r=await request({url:'/boost/config'});if(!valid(token))return;smsReady.value=!!r.data.smsReady;ready.value=true;await history()}catch(e){if(valid(token))error.value=e.message}})
async function run(action){if(busy.value)return;const token=getToken();busy.value=true;error.value='';try{await action(token)}catch(e){if(valid(token)&&e!=='cancel'&&e!=='close')error.value=e.message||'操作未完成，请刷新核对'}finally{if(valid(token))busy.value=false}}
const sendCode=()=>run(async token=>{if(!/^1[3-9]\d{9}$/.test(phone.value))throw Error('请输入正确的手机号');const r=await request({url:endpoint+'/phone/code',method:'post',data:{phone:phone.value}});if(!valid(token))return;challenge.value=r.data.challengeId;remaining.value=r.data.retryAfter;until=Date.now()+r.data.retryAfter*1000;phoneTicket.value='';ElMessage.success('验证码已发送')})
const verify=()=>run(async token=>{const r=await request({url:endpoint+'/phone/verify',method:'post',data:{challengeId:challenge.value,code:code.value}});if(valid(token)){phoneTicket.value=r.data.challengeId;code.value=''}})
async function upload(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;await run(async token=>{if(form.images.length>=3||file.size>5*1024*1024)throw Error('最多 3 张，每张不超过 5MB');const data=new FormData();data.append('file',file);const r=await request({url:endpoint+'/proof',method:'post',headers:{'Content-Type':'multipart/form-data',repeatSubmit:false},data});if(valid(token)){form.images.push(r.data.url);await authorizeMedia([r.data.url])}})}
const save=()=>run(async token=>{if(form.note.trim().length<2)throw Error('请填写具体更正原因');if(changePhone.value&&!phoneTicket.value)throw Error('请先完成新手机号核验');if(!form.images.length)throw Error('至少保留一张店铺证明');await ElMessageBox.confirm('更正资料后将重新审核，并下架当前出售商品。原材料保留在历史中。','确认更正');if(!valid(token))return;await request({url:endpoint,method:'put',data:{...form,images:[...form.images],expectedRevision:props.member.shopRevision||0,phoneTicket:changePhone.value?phoneTicket.value:''}});if(valid(token)){ElMessage.success('已更正，等待重新审核');emit('saved')}})
</script>
<style scoped>.shop-editor{margin-top:24px;border-top:1px solid #eee;padding-top:18px}.shop-editor p{color:#687183;line-height:1.7;font-size:13px}.shop-editor .el-form-item{margin-top:18px}.phone-code{display:flex;gap:8px;min-width:0}.phone-code .el-input{min-width:90px}.proof-list{display:flex;gap:12px;margin-bottom:12px}.proof-list>div{display:flex;flex-direction:column}.el-image{width:84px;height:84px;border-radius:8px;margin:4px}.history{padding:18px 0;border-top:1px solid #eee}</style>
